            "wms_srs" "EPSG:4326"
            "wms_server_version" "1.3.0"
            "wms_format" "image/png"
        END
    END
    LAYER
        NAME "country_bounds"
        TYPE RASTER
        STATUS ON
        CONNECTIONTYPE WMS
        CONNECTION "https://demo.mapserver.org/cgi-bin/wms?"
        PROJECTION
            "EPSG:4326"
        END
        METADATA
            "wms_name" "country_bounds"
